Here's a complete example with both `DataRow` and `DynamicData` approaches:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline constant values ---
    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00)]   // 10% off
    [DataRow(100.00, 0.00, 100.00)]  // no discount
    [DataRow(50.00, 0.50, 25.00)]    // 50% off
    [DataRow(200.00, 1.00, 0.00)]    // 100% off
    public void ApplyDiscount_ReturnsExpected(double price, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/non-constant test cases ---
    [TestMethod]
    [DynamicData(nameof(BulkDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_BulkScenarios(decimal price, decimal discount, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discount);
        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    private static IEnumerable<object[]> BulkDiscountCases()
    {
        yield return new object[] { 999.99m, 0.15m, 849.99m, "large order 15%" };
        yield return new object[] { 0.01m, 0.10m, 0.01m, "sub-penny rounds up" };
        yield return new object[] { 1000m, 0.333m, 667.00m, "repeating decimal" };
    }

    // --- Edge cases / validation ---
    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_InvalidInput_Throws(int quantity, double unitPrice)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)unitPrice));
    }

    [TestMethod]
    [DataRow(100.00, -0.01)]
    [DataRow(100.00, 1.01)]
    public void ApplyDiscount_InvalidRate_Throws(double price, double discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discount));
    }
}
```

**Key best practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Compile-time constants; simple scalar inputs |
| `[DynamicData]` | Complex types, computed values, or descriptive labels |
| `TestInitialize` | Shared setup without constructor coupling |
| Descriptive failure messages | Easier debugging of parameterized failures |
| Edge/validation cases | Separate test methods for error paths |

**Notes:**
- `DataRow` only supports primitive/constant types — use `double` and cast to `decimal` inside the method.
- `DynamicData` with `DynamicDataSourceType.Method` keeps test data close to the test and supports `decimal` directly.
- Include a `string scenario` parameter in dynamic tests for readable failure output.
